import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_solution(a, b):
    if a < 0 or b < 0:
        return None
    try:
        value = 2**a * (5**b) + 625
        if is_perfect_square(value):
            N = math.isqrt(value)
            return (a, b, N)
        return None
    except OverflowError:
        # Handle cases where the number gets too large, although 12 should be fine
        return None

# 1. Verify (4, 5)
case_4_5 = check_solution(4, 5)
print(f"Verification of (4, 5): {case_4_5}")

# 2. Targeted search near (3, 4) and (4, 5) for 0 <= a, b <= 12
print("\nStarting targeted computational search...")
found_solutions = set()
search_range_a = range(0, 13)
search_range_b = range(0, 13)

# Search a small local area to fulfill the requirement (e.g., up to 6 for both)
