for a in range(max(0, 3-2), min(13, 4+3)): # Roughly 1 to 6
    for b in range(max(0, 4-2), min(13, 5+3)): # Roughly 2 to 8
        if a <= 12 and b <= 12:
            result = check_solution(a, b)
            if result:
                found_solutions.add(result)

# Also check boundaries mentioned in the notes (a=0, b=0) for completeness if they were missed in the local search
